import json
import itertools

def solve_puzzle():
    # Input variables
    houses = [1, 2]  # Houses numbered from left (1) to right (2)
    names = ["Eric", "Arnold"]
    book_genres = ["science fiction", "mystery"]

    solutions = []

    # Iterate over all permutations for names and book genres
    for name_perm in itertools.permutations(names):
        house_to_name = {house: name_perm[i] for i, house in enumerate(houses)}

        for book_perm in itertools.permutations(book_genres):
            house_to_book = {house: book_perm[i] for i, house in enumerate(houses)}

            # Constraint 1: Eric is directly left of the person who loves mystery books.
            house_of_eric = next(h for h, n in house_to_name.items() if n == "Eric")
            house_of_mystery = next(h for h, b in house_to_book.items() if b == "mystery")

            if house_of_eric + 1 == house_of_mystery:
                solutions.append((house_to_name, house_to_book))

    # Select the first (and should be unique) solution
    if not solutions:
        raise ValueError("No solution found for the given puzzle constraints.")
    house_to_name, house_to_book = solutions[0]

    # Prepare output
    output = {
        "solution": {
            "header": ["House", "Name", "BookGenre"],
            "rows": []
        }
    }

    for h in sorted(houses):
        row = [str(h), house_to_name[h], house_to_book[h]]
        output["solution"]["rows"].append(row)

    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False, indent=2))
